validator:
function validate(input) {
  const [{ students = [] }] = input;
  for (const [id, , , age] of students) {
    if (id === null) return 'id cannot be null.';
    if (age === null) return 'age cannot be null.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const firsts = ['Mason', 'Ava', 'Taylor', 'Georgia', 'Thomas', 'Hall', 'King'];
  const lasts = ['King', 'Wright', 'Hall', 'Thompson', 'Moore', 'Mason', 'Taylor'];
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const students = [];
  for (let i = 0; i < rows; i++) {
    const id = size === 'small' ? Math.floor(rand() * 6) + 1 : i + 1;
    students.push([id, pick(firsts), pick(lasts), Math.floor(rand() * 20) + 3]);
  }
  return [{ students }];
}
